    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    prev_bids = []
    dangerous_prev = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(float(bid))
                if opp.get('budget', 0) > 0:
                    dangerous_prev.append(float(bid))

    if not alive:
        return max(0.0, min(float(budget), DAILY_SALARY * 0.35))

    units = int(supply // WATER_REQ)
    tight = units <= 1

    bob_like = []
    for opp in alive:
        prev = opp.get('previous_trace', {})
        bid = prev.get('bid') if prev else None
        if bid is not None and 45 <= float(bid) <= 80:
            bob_like.append(float(bid))

    if bob_like:
        target_competitor = max(bob_like)
    elif dangerous_prev:
        target_competitor = max(dangerous_prev)
    elif prev_bids:
        target_competitor = max(prev_bids)
    else:
        target_competitor = DAILY_SALARY * 0.55

    urgency = 0
    if hp <= 2:
        urgency += 3
    elif hp <= 4:
        urgency += 2
    elif hp <= 6:
        urgency += 1

    if no_water_days >= 2:
        urgency += 3
    elif no_water_days >= 1:
        urgency += 1

    if tight:
        urgency += 2

    if day >= 8:
        urgency += 1

    if urgency >= 6:
        bid = max(DAILY_SALARY * 0.95, target_competitor + 8.0)
    elif urgency >= 4:
        bid = max(DAILY_SALARY * 0.82, target_competitor + 3.0)
    elif urgency >= 2:
        if tight:
            bid = max(DAILY_SALARY * 0.72, target_competitor + 1.5)
        else:
            bid = max(DAILY_SALARY * 0.58, target_competitor * 0.92)
    else:
        if tight:
            bid = max(DAILY_SALARY * 0.62, min(target_competitor + 1.0, DAILY_SALARY * 0.9))
        else:
            bid = DAILY_SALARY * 0.42

    if budget < DAILY_SALARY * 0.6:
        bid = min(bid, budget * 0.9)

    if hp > 6 and no_water_days == 0 and not tight:
        bid = min(bid, DAILY_SALARY * 0.48)

    return max(0.0, min(float(budget), float(bid)))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append((opp_id, opp))

    if not alive_opps:
        return min(budget, DAILY_SALARY * 0.4)

    # Read yesterday bids for immediate reaction
    prev_bids = []
    for _, opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0

    # Estimate how scarce water is today; higher supply -> bid less
    # Normalize scarcity: at MIN_SUPPLY scarcity is high, at MAX_SUPPLY scarcity is low
    scarcity = 1.0 - max(0.0, min(1.0, (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)))

    # Base bid: target around a fraction of salary, adjusted by scarcity
    base = DAILY_SALARY * (0.45 + 0.25 * scarcity)

    # If someone previously bid extremely high, we must not lose all allocation.
    # Use a cap so we don't bleed budget.
    if highest_prev_bid >= DAILY_SALARY * 1.35:
        # Cindy-like pressure: bid closer to salary to stay competitive
        pressure_bid = DAILY_SALARY * (0.75 + 0.15 * scarcity)
    elif highest_prev_bid >= DAILY_SALARY * 0.85:
        pressure_bid = DAILY_SALARY * (0.6 + 0.1 * scarcity)
    else:
        pressure_bid = base

    # If low HP or already starving, increase bid sharply
    if hp <= 2.0 or no_water_days >= 2:
        pressure_bid *= 1.25

    # Slightly reduce bid if we are healthy and have budget slack
    if hp >= 6.0 and no_water_days == 0:
        pressure_bid *= 0.9

    # Ensure we don't bid more than we can afford
    bid = min(budget, pressure_bid)

    # If budget is very low, still try to bid enough to avoid further starvation
    if budget <= DAILY_SALARY * 0.2:
        bid = min(budget, DAILY_SALARY * 0.25)

    # Keep bid non-negative
    if bid < 0.0:
        bid = 0.0

    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(budget, DAILY_SALARY * 0.4)

    # Collect yesterday's bids from opponents
    prev_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            prev_bids.append(prev['bid'])

    # Determine a target bid based on yesterday's maximum
    if prev_bids:
        max_prev = max(prev_bids)
    else:
        max_prev = 0.0

    # Base bid: need to secure water if hp is low
    if hp <= 2:
        base = DAILY_SALARY * 0.9
    elif hp <= 4:
        base = DAILY_SALARY * 0.7
    else:
        base = DAILY_SALARY * 0.5

    # Adjust based on competition: if max_prev is high, we need to beat it
    target = max(base, max_prev + 1.0)

    # Consider supply: if supply is very low, we might need to bid higher
    if supply < 18:
        target *= 1.2
    elif supply > 22:
        target *= 0.8

    # Ensure we don't exceed budget or go negative
    bid = min(budget, max(0.0, target))
    return bid
